def max_sum(arr):
    def longest_increasing_subsequence(arr):
        n = len(arr)
        lis = [1] * n
        for i in range(1, n):
            for j in range(i):
                if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                    lis[i] = lis[j] + 1
        return lis

    def longest_decreasing_subsequence(arr, end_index):
        n = len(arr)
        lds = [1] * n
        for i in range(n - 2, -1, -1):
            for j in range(i + 1, n):
                if arr[i] > arr[j] and lds[i] < lds[j] + 1:
                    lds[i] = lds[j] + 1
        return lds

    lis = longest_increasing_subsequence(arr)
    max_sum = 0
    for i in range(len(arr)):
        lds = longest_decreasing_subsequence(arr, i)
        current_sum = lis[i] + lds[i]
        max_sum = max(max_sum, current_sum)

